/**
 * Real Image Intelligence Engine — Visual Intelligence v1.1.0
 *
 * Provides genuine, high-resolution, CC-licensed and verified photography
 * for websites generated by Achu Coding Agent.
 *
 * Primary Provider: Wikimedia Commons REST API (free, fast, legal, 80M+ CC media)
 * Secondary Provider: Curated high-resolution verified photography library
 * Download Engine: Validates image headers, magic bytes, dimensions, and persists to workspace
 * Manifest Engine: Tracks verified image assets, paths, licenses, and browser URLs
 * Auto-Repair: Detects broken images in real browser and hot-replaces with verified sources
 */

import fs from "node:fs";
import path from "node:path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ImageSearchResult {
  id: string;
  title: string;
  url: string;
  thumbnailUrl: string;
  source: "wikimedia" | "unsplash" | "curated";
  license?: string;
  creator?: string;
  attribution?: string;
  width?: number;
  height?: number;
  altText: string;
  category?: string;
}

export interface ImageRequirement {
  slot: "hero" | "gallery" | "feature" | "showcase" | "detail" | "profile" | "background";
  description: string;
  query: string;
  aspectRatio: "16:9" | "4:3" | "1:1" | "21:9" | "3:4";
}

export interface ImageAssetManifestEntry {
  id: string;
  slot: string;
  subject: string;
  title: string;
  provider: "wikimedia" | "unsplash" | "curated";
  originalUrl: string;
  localPath: string;
  browserUrl: string;
  width: number;
  height: number;
  mimeType: string;
  license: string;
  attribution: string;
  validationStatus: "verified" | "failed" | "unverified";
}

export interface ImageAssetManifest {
  version: string;
  industry: string;
  generatedAt: string;
  assets: ImageAssetManifestEntry[];
}

