// ---------------------------------------------------------------------------
// Negative filter terms to eliminate irrelevant Wikimedia matches
// ---------------------------------------------------------------------------

const AUTOMOTIVE_DISQUALIFIERS = [
  "train", "railway", "railroad", "locomotive", "tram", "bus", "station",
  "football", "soccer", "pitch", "stadium", "rugby", "cricket", "game",
  "statue", "monument", "painting", "sculpture", "building", "church", "cathedral",
  "stamp", "coin", "medal", "drawing", "diagram", "schematic", "map", "chart",
  "logo", "crest", "coat of arms", "flag", "signboard", "plaque",
];

// ---------------------------------------------------------------------------
// Wikimedia Commons API Provider
// ---------------------------------------------------------------------------

export async function searchWikimediaCommons(
  query: string,
  limit = 4,
  categoryHint?: string
): Promise<ImageSearchResult[]> {
  const isAutomotive = categoryHint === "automotive" || /\b(car|automotive|supercar|sports\s*car|vehicle|automobile|bmw|porsche|audi|ferrari|lamborghini)\b/i.test(query);

  // Clean and focus the search term
  let cleanedQuery = query
    .replace(/[^\w\s-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // If automotive, ensure search is specifically targeted at automotive photography
  if (isAutomotive && !/\b(car|automobile|vehicle|sports car)\b/i.test(cleanedQuery)) {
    cleanedQuery = `${cleanedQuery} sports car`;
  }

  const endpoint = `https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(
    cleanedQuery
  )}&gsrnamespace=6&gsrlimit=${Math.min(limit * 3, 20)}&prop=imageinfo&iiprop=url|size|extmetadata&iiurlwidth=1280&format=json`;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 6000);

  try {
    const res = await fetch(endpoint, {
      headers: { "User-Agent": "AchuCodingAgent/1.1.0 (contact@workswithachu.me)" },
      signal: controller.signal,
    });
    if (!res.ok) return [];

    const data = await res.json();
    const pages = data.query?.pages || {};
    const results: ImageSearchResult[] = [];

    for (const [pageId, p] of Object.entries(pages) as [string, any][]) {
      const info = p.imageinfo?.[0];
      if (!info) continue;

      // Filter out non-image extensions (e.g. .pdf, .djvu, .tif, .ogg)
      const ext = path.extname(p.title || "").toLowerCase();
      if (![".jpg", ".jpeg", ".png", ".webp"].includes(ext)) continue;

      const rawTitle = p.title.replace(/^File:/, "").replace(/\.[^/.]+$/, "");
      const cleanTitle = rawTitle.replace(/[_-]+/g, " ").trim();
      const lowerTitle = cleanTitle.toLowerCase();

      // Check for disqualifiers when searching automotive
      if (isAutomotive) {
        const isDisqualified = AUTOMOTIVE_DISQUALIFIERS.some((d) => lowerTitle.includes(d));
        if (isDisqualified) continue;
      }

      const license = info.extmetadata?.LicenseShortName?.value || "Creative Commons";
      const creator = (info.extmetadata?.Artist?.value || "Wikimedia Contributor")
        .replace(/<[^>]+>/g, "")
        .replace(/\s+/g, " ")
        .trim();

      const thumbUrl = info.thumburl || info.url;
      const fullUrl = info.url || thumbUrl;

      results.push({
        id: `wiki-${pageId}`,
        title: cleanTitle,
        url: fullUrl,
        thumbnailUrl: thumbUrl,
        source: "wikimedia",
        license,
        creator: creator.slice(0, 60),
        attribution: `${cleanTitle} by ${creator} (${license}) via Wikimedia Commons`,
        width: info.width || 1280,
        height: info.height || 720,
        altText: `${cleanTitle} authentic photography`,
        category: categoryHint,
      });

      if (results.length >= limit) break;
    }

    return results;
  } catch {
    return [];
  } finally {
    clearTimeout(timer);
  }
}

// ---------------------------------------------------------------------------
// Multi-Tier Image Search Engine
// ---------------------------------------------------------------------------

/**
 * Searches for high-quality, genuine photography for a specific query.
 * Falls back to curated topic datasets if network API is unreachable or returns irrelevant results.
 */
export async function searchImages(
  query: string,
  limit = 4,
  categoryHint?: string
): Promise<ImageSearchResult[]> {
  const lower = query.toLowerCase();

  // Determine intent category
  const isAuto =
    categoryHint === "automotive" ||
    /\b(car|cars|automotive|automobile|automobiles|vehicle|vehicles|dealership|supercar|supercars|sports\s*car|sports\s*cars|bmw|porsche|audi|ferrari|lamborghini|m4|m3|amg|mercedes)\b/.test(
      lower
    );

  const isRealEstate =
    categoryHint === "real_estate" ||
    /\b(real\s*estate|villa|house|apartment|property|interior|mansion|living\s*room|kitchen|penthouse)\b/.test(
      lower
    );

  const isRestaurant =
    categoryHint === "restaurant" ||
    categoryHint === "restaurant_hospitality" ||
    /\b(restaurant|food|dining|dish|culinary|bistro|cafe|kitchen|chef|menu|entree)\b/.test(
      lower
    );

  const isLuxury =
    categoryHint === "luxury_brand" ||
    categoryHint === "luxury_fashion" ||
    (/\b(luxury|watch|timepiece|jewelry|fashion|gold|horlogerie)\b/.test(lower) && !isAuto);

  const isEcommerce =
    categoryHint === "ecommerce" ||
    /\b(store|shop|product|catalog|headphones|keyboard|smartwatch|cart|checkout)\b/.test(
      lower
    );

  // 1. Try real-time Wikimedia search (only if query is descriptive and not just brand name)
  const isGenericQuery = /^[a-z0-9\s_-]{1,25}$/i.test(query.trim()) && !query.includes(" ");
  if (!isGenericQuery) {
    const wikiResults = await searchWikimediaCommons(query, limit, isAuto ? "automotive" : categoryHint);
    if (wikiResults.length >= limit) {
      return wikiResults;
    }
  }

  // 2. High-precision curated photographic catalog
  if (isAuto) {
    if (lower.includes("front") || lower.includes("fascia") || lower.includes("grille") || lower.includes("aerodynamic")) {
      return [...CURATED_IMAGE_DATABASE.automotive_front, ...CURATED_IMAGE_DATABASE.automotive_hero].slice(0, limit);
    }
    if (lower.includes("interior") || lower.includes("cockpit") || lower.includes("cabin") || lower.includes("seat")) {
      return [...CURATED_IMAGE_DATABASE.automotive_interior, ...CURATED_IMAGE_DATABASE.automotive_collection].slice(0, limit);
    }
    if (lower.includes("rear") || lower.includes("diffuser") || lower.includes("exhaust")) {
      return [...CURATED_IMAGE_DATABASE.automotive_rear, ...CURATED_IMAGE_DATABASE.automotive_collection].slice(0, limit);
    }
    if (lower.includes("gallery") || lower.includes("collection") || lower.includes("showroom")) {
      return CURATED_IMAGE_DATABASE.automotive_collection.slice(0, limit);
    }
    return [
      ...CURATED_IMAGE_DATABASE.automotive_hero,
      ...CURATED_IMAGE_DATABASE.automotive_collection,
      ...CURATED_IMAGE_DATABASE.automotive_front,
      ...CURATED_IMAGE_DATABASE.automotive_interior,
      ...CURATED_IMAGE_DATABASE.automotive_rear,
    ].slice(0, limit);
  }

  if (isRealEstate) {
    return CURATED_IMAGE_DATABASE.real_estate.slice(0, limit);
  }

  if (isRestaurant) {
    return CURATED_IMAGE_DATABASE.restaurant.slice(0, limit);
  }

  if (isLuxury) {
    return CURATED_IMAGE_DATABASE.luxury_brand.slice(0, limit);
  }

  if (isEcommerce) {
    return CURATED_IMAGE_DATABASE.ecommerce.slice(0, limit);
  }

  // Generic SaaS/Tech fallback
  return CURATED_IMAGE_DATABASE.saas_tech.slice(0, limit);
}

// ---------------------------------------------------------------------------
// Image Downloader & Asset Validator
// ---------------------------------------------------------------------------

export async function downloadAndValidateImage(
  imageUrl: string,
  destPath: string,
  options?: { timeoutMs?: number; maxBytes?: number; minBytes?: number }
): Promise<{
  success: boolean;
  bytes: number;
  localPath?: string;
  mimeType?: string;
  width?: number;
  height?: number;
  error?: string;
}> {
  const timeoutMs = options?.timeoutMs ?? 12000;
  const maxBytes = options?.maxBytes ?? 15 * 1024 * 1024; // 15MB max
  const minBytes = options?.minBytes ?? 500; // 500 bytes min

  if (!imageUrl || !imageUrl.startsWith("http")) {
    return { success: false, bytes: 0, error: `Invalid image URL: '${imageUrl}'` };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(imageUrl, {
      headers: {
        "User-Agent": "AchuCodingAgent/1.1.0 (contact@workswithachu.me)",
        Accept: "image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
      },
      signal: controller.signal,
    });

    if (!res.ok) {
      return { success: false, bytes: 0, error: `HTTP ${res.status}: ${res.statusText}` };
    }

    const contentType = (res.headers.get("content-type") || "").toLowerCase();
    if (contentType.includes("text/html") || contentType.includes("text/plain")) {
      return { success: false, bytes: 0, error: `Server returned non-image content-type: ${contentType}` };
    }

    const buffer = Buffer.from(await res.arrayBuffer());

    if (buffer.length < minBytes) {
      return { success: false, bytes: buffer.length, error: `Image file too small (${buffer.length} bytes, min ${minBytes})` };
    }

    if (buffer.length > maxBytes) {
      return { success: false, bytes: buffer.length, error: `Image file exceeds maximum size (${buffer.length} bytes, max ${maxBytes})` };
    }

    // Verify magic bytes:
    // JPEG: 0xFF, 0xD8, 0xFF
    const isJpeg = buffer[0] === 0xff && buffer[1] === 0xd8;
    // PNG: 0x89, 'P', 'N', 'G'
    const isPng = buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e && buffer[3] === 0x47;
    // WebP: 'RIFF'....'WEBP'
    const isWebP = buffer.slice(0, 4).toString("ascii") === "RIFF" && buffer.slice(8, 12).toString("ascii") === "WEBP";
    // SVG: contains <svg
    const headText = buffer.slice(0, 200).toString("utf8").toLowerCase();
    const isSvg = headText.includes("<svg") && buffer.slice(-200).toString("utf8").toLowerCase().includes("</svg>");

    // Reject HTML error pages returning status 200
    if (headText.includes("<!doctype html") || headText.includes("<html") || headText.includes("<head") || headText.includes("{\"error\"")) {
      return { success: false, bytes: buffer.length, error: "Server returned HTML/JSON error page instead of binary image" };
    }

    if (!isJpeg && !isPng && !isWebP && !isSvg) {
      return { success: false, bytes: buffer.length, error: "File format is not a recognized image type (invalid magic bytes)" };
    }

    const detectedMime = isJpeg ? "image/jpeg" : isPng ? "image/png" : isWebP ? "image/webp" : "image/svg+xml";

    // Ensure destination directory exists
    const dir = path.dirname(destPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    fs.writeFileSync(destPath, buffer);

    // Dual-mirroring: If saved to `images/...`, mirror to `public/images/...`
    // If saved to `public/images/...`, mirror to `images/...`
    // This guarantees both Static (root-based) and React/Vite (public-based) scaffolds find the assets!
    try {
      const normalized = destPath.replace(/\\/g, "/");
      if (normalized.includes("/images/") && !normalized.includes("/public/images/")) {
        const mirrorPath = normalized.replace("/images/", "/public/images/");
        const mirrorDir = path.dirname(mirrorPath);
        if (!fs.existsSync(mirrorDir)) fs.mkdirSync(mirrorDir, { recursive: true });
        fs.writeFileSync(mirrorPath, buffer);
      } else if (normalized.includes("/public/images/")) {
        const mirrorPath = normalized.replace("/public/images/", "/images/");
        const mirrorDir = path.dirname(mirrorPath);
        if (!fs.existsSync(mirrorDir)) fs.mkdirSync(mirrorDir, { recursive: true });
        fs.writeFileSync(mirrorPath, buffer);
      }
    } catch {}

    return {
      success: true,
      bytes: buffer.length,
      localPath: destPath,
      mimeType: detectedMime,
    };
  } catch (err: any) {
    return { success: false, bytes: 0, error: err.message || String(err) };
  } finally {
    clearTimeout(timer);
  }
}

// ---------------------------------------------------------------------------
// Autonomous Asset Provisioning Engine
// ---------------------------------------------------------------------------

/**
 * Automatically provisions all required photographic visual assets for a project
 * into both workspace `images/` and `public/images/`, and writes `image-manifest.json`.
 */
export async function provisionVisualAssets(
  workspaceRoot: string,
  productType: string,
  taskPrompt: string
): Promise<ImageAssetManifest> {
  const isAuto = productType === "automotive" || /\b(car|automotive|automobile|supercar|sports\s*car|vehicle)\b/i.test(taskPrompt);
  const isRealEstate = productType === "real_estate" || /\b(real\s*estate|villa|mansion|property)\b/i.test(taskPrompt);
  const isRestaurant = productType === "restaurant_hospitality" || /\b(restaurant|food|dining|dish|bistro|cafe)\b/i.test(taskPrompt);
  const isLuxury = productType === "luxury_fashion" || /\b(luxury|watch|timepiece|jewelry)\b/i.test(taskPrompt);
  const isEcommerce = productType === "ecommerce" || /\b(store|shop|ecommerce|catalog)\b/i.test(taskPrompt);

  const imagesDir = path.join(workspaceRoot, "images");
  const publicImagesDir = path.join(workspaceRoot, "public", "images");

  if (!fs.existsSync(imagesDir)) fs.mkdirSync(imagesDir, { recursive: true });
  if (!fs.existsSync(publicImagesDir)) fs.mkdirSync(publicImagesDir, { recursive: true });

  const manifestEntries: ImageAssetManifestEntry[] = [];

  let requirements: Array<{ slot: string; subject: string; searchTerms: string; defaultFilename: string }> = [];

  if (isAuto) {
    requirements = [
      { slot: "hero", subject: "Luxury Sports Car Exterior", searchTerms: "luxury sports car exterior", defaultFilename: "hero-car.jpg" },
      { slot: "front", subject: "Aerodynamic Front Fascia & Headlights", searchTerms: "sports car front view", defaultFilename: "front-car.jpg" },
      { slot: "interior", subject: "Driver Cockpit & Sport Seats", searchTerms: "luxury car interior cockpit", defaultFilename: "cockpit-car.jpg" },
      { slot: "rear", subject: "Rear Diffuser & Quad Exhaust", searchTerms: "sports car rear view", defaultFilename: "rear-car.jpg" },
      { slot: "gallery_1", subject: "GT Sports Coupe Edition", searchTerms: "sports coupe exterior", defaultFilename: "gallery-model-1.jpg" },
      { slot: "gallery_2", subject: "Roadster Convertible Edition", searchTerms: "sports car roadster convertible", defaultFilename: "gallery-model-2.jpg" },
      { slot: "gallery_3", subject: "Track Competition Edition", searchTerms: "race track sports car", defaultFilename: "gallery-model-3.jpg" },
      { slot: "gallery_4", subject: "Bespoke Cockpit Detailing", searchTerms: "luxury sports car interior", defaultFilename: "gallery-model-4.jpg" },
    ];
  } else if (isRealEstate) {
    requirements = [
      { slot: "hero", subject: "Luxury Villa Exterior with Pool", searchTerms: "luxury villa modern architecture", defaultFilename: "hero-villa.jpg" },
      { slot: "living", subject: "Panoramic Contemporary Living Room", searchTerms: "contemporary luxury living room", defaultFilename: "living-room.jpg" },
      { slot: "kitchen", subject: "Gourmet Marble Kitchen Island", searchTerms: "designer kitchen luxury", defaultFilename: "kitchen.jpg" },
    ];
  } else if (isRestaurant) {
    requirements = [
      { slot: "hero", subject: "Fine Dining Restaurant Ambiance", searchTerms: "fine dining restaurant interior", defaultFilename: "hero-restaurant.jpg" },
      { slot: "dish", subject: "Artisanal Plated Culinary Creation", searchTerms: "gourmet plated dish", defaultFilename: "plated-dish.jpg" },
      { slot: "chef", subject: "Master Culinary Chef", searchTerms: "chef cooking restaurant kitchen", defaultFilename: "master-chef.jpg" },
    ];
  } else if (isLuxury) {
    requirements = [
      { slot: "hero", subject: "Haute Horlogerie Swiss Timepiece", searchTerms: "luxury timepiece watch", defaultFilename: "hero-timepiece.jpg" },
      { slot: "detail", subject: "Mechanical Movement Craftsmanship", searchTerms: "luxury watch dial detail", defaultFilename: "watch-detail.jpg" },
    ];
  } else if (isEcommerce) {
    requirements = [
      { slot: "product_1", subject: "Flagship Acoustic Wireless Headphones", searchTerms: "wireless headphones", defaultFilename: "headphones.jpg" },
      { slot: "product_2", subject: "Mechanical Gaming Keyboard", searchTerms: "mechanical keyboard", defaultFilename: "keyboard.jpg" },
      { slot: "product_3", subject: "Smart Connected Timepiece", searchTerms: "smartwatch modern", defaultFilename: "smartwatch.jpg" },
    ];
  } else {
    requirements = [
      { slot: "hero", subject: "High-Performance Modern Workspace", searchTerms: "modern tech workspace", defaultFilename: "hero-workspace.jpg" },
      { slot: "feature", subject: "Collaborative Office Setup", searchTerms: "modern office technology", defaultFilename: "feature-office.jpg" },
    ];
  }

  for (const req of requirements) {
    const destFile = path.join(imagesDir, req.defaultFilename);
    const searchResults = await searchImages(req.searchTerms, 3, productType);
    let chosen = searchResults[0];

    if (!chosen && isAuto) {
      chosen = CURATED_IMAGE_DATABASE.automotive_hero[0];
    } else if (!chosen) {
      chosen = CURATED_IMAGE_DATABASE.saas_tech[0];
    }

    const dlUrl = chosen.thumbnailUrl || chosen.url;
    const dlRes = await downloadAndValidateImage(dlUrl, destFile);

    manifestEntries.push({
      id: chosen.id,
      slot: req.slot,
      subject: req.subject,
      title: chosen.title,
      provider: chosen.source,
      originalUrl: chosen.url,
      localPath: `images/${req.defaultFilename}`,
      browserUrl: `images/${req.defaultFilename}`,
      width: chosen.width || 1200,
      height: chosen.height || 800,
      mimeType: dlRes.mimeType || "image/jpeg",
      license: chosen.license || "Free to use",
      attribution: chosen.attribution || `${chosen.title} via ${chosen.source}`,
      validationStatus: dlRes.success ? "verified" : "failed",
    });
  }

  const manifest: ImageAssetManifest = {
    version: "1.1.0",
    industry: productType,
    generatedAt: new Date().toISOString(),
    assets: manifestEntries,
  };

  const manifestJson = JSON.stringify(manifest, null, 2);
  fs.writeFileSync(path.join(workspaceRoot, "image-manifest.json"), manifestJson, "utf8");
  fs.writeFileSync(path.join(publicImagesDir, "..", "image-manifest.json"), manifestJson, "utf8");

  return manifest;
}

// ---------------------------------------------------------------------------
// Automatic Image Repair Engine
// ---------------------------------------------------------------------------

/**
 * Hot-repairs a broken image detected in the real browser.
 * Replaces the failed image on disk and updates HTML/JSX references.
 */
export async function repairBrokenImage(
  workspaceRoot: string,
  brokenSrc: string,
  altText: string,
  context?: string
): Promise<{ success: boolean; newSrc?: string; newAlt?: string; error?: string }> {
  const combinedContext = `${brokenSrc} ${altText} ${context || ""}`.toLowerCase();

  // Search for high-quality alternative
  let searchCategory = "saas_tech";
  if (/\b(car|automotive|automobile|bmw|porsche|sports\s*car|vehicle|diffuser|grille|cockpit|exhaust|motor)\b/i.test(combinedContext)) {
    searchCategory = "automotive";
  } else if (/\b(villa|house|room|living|kitchen|estate|mansion)\b/i.test(combinedContext)) {
    searchCategory = "real_estate";
  } else if (/\b(food|restaurant|dish|chef|dining|plate)\b/i.test(combinedContext)) {
    searchCategory = "restaurant";
  } else if (/\b(watch|timepiece|luxury|gold|jewelry)\b/i.test(combinedContext)) {
    searchCategory = "luxury_brand";
  }

  const candidates = await searchImages(altText || combinedContext, 4, searchCategory);
  if (candidates.length === 0) {
    return { success: false, error: `No verified replacement found for '${altText}'` };
  }

  const replacement = candidates[0];
  const filename = `repaired-${Date.now().toString(36)}-${replacement.id.slice(0, 10)}.jpg`;
  const destPath = path.join(workspaceRoot, "images", filename);

  const dlRes = await downloadAndValidateImage(replacement.thumbnailUrl || replacement.url, destPath);
  if (!dlRes.success) {
    return { success: false, error: `Failed to download replacement image: ${dlRes.error}` };
  }

  const newBrowserUrl = `images/${filename}`;

  // Update HTML files in workspace
  const htmlFiles = ["index.html", "public/index.html"];
  for (const hf of htmlFiles) {
    const fullHtml = path.join(workspaceRoot, hf);
    if (fs.existsSync(fullHtml)) {
      let content = fs.readFileSync(fullHtml, "utf8");
      // Replace exact broken src
      if (brokenSrc && content.includes(brokenSrc)) {
        content = content.split(brokenSrc).join(newBrowserUrl);
        fs.writeFileSync(fullHtml, content, "utf8");
      }
    }
  }

  // Update React App.jsx if present
  const jsxFiles = ["src/App.jsx", "src/App.tsx"];
  for (const jf of jsxFiles) {
    const fullJsx = path.join(workspaceRoot, jf);
    if (fs.existsSync(fullJsx)) {
      let content = fs.readFileSync(fullJsx, "utf8");
      if (brokenSrc && content.includes(brokenSrc)) {
        content = content.split(brokenSrc).join(newBrowserUrl);
        fs.writeFileSync(fullJsx, content, "utf8");
      }
    }
  }

  return {
    success: true,
    newSrc: newBrowserUrl,
    newAlt: replacement.altText,
  };
}
